const crypto = require("crypto");

const SECRET = "super-secret-key";

function sign(payload) {
  const hmac = crypto.createHmac("sha256", SECRET).update(payload).digest("hex");
  return `${payload}.${hmac}`;
}

function verify(token) {
  const [payload, hmac] = token.split(".");
  const expected = crypto.createHmac("sha256", SECRET).update(payload).digest("hex");
  return hmac === expected;
}

const token = sign("userId=42");
console.log(verify(token)); // true
console.log(verify(token + "tampered")); // false

const express = require("express");
const app = express();

const hits = new Map();
const LIMIT = 5;
const WINDOW_MS = 10_000;

function rateLimiter(req, res, next) {
  const ip = req.ip;
  const now = Date.now();
  const record = hits.get(ip) || { count: 0, start: now };

  if (now - record.start > WINDOW_MS) {
    record.count = 0;
    record.start = now;
  }

  record.count++;
  hits.set(ip, record);

  if (record.count > LIMIT) {
    return res.status(429).send("Too many requests");
  }
  next();
}

app.use(rateLimiter);
app.get("/", (req, res) => res.send("OK"));
app.listen(3000);

const express = require("express");
const app = express();

const cache = new Map();
const TTL_MS = 30_000;

function cacheMiddleware(req, res, next) {
  const key = req.originalUrl;
  const cached = cache.get(key);

  if (cached && Date.now() - cached.time < TTL_MS) {
    return res.json(cached.data);
  }

  const originalJson = res.json.bind(res);
  res.json = (data) => {
    cache.set(key, { data, time: Date.now() });
    originalJson(data);
  };
  next();
}

app.get("/expensive", cacheMiddleware, (req, res) => {
  res.json({ result: Math.random() });
});

app.listen(3000);
